        gloss: { estuviera: '„ojalá estuviera” = de-aș fi', daño: '„hacer daño” = a face rău', susto: 'sperietură', equivoca: '„se equivoca” = greșește', desea: '„desea” = urează', cogerla: 'a o prinde', entera: 'întreagă' },
